/**
 * Everything one structured question type needs, in one place: how it
 * renders, what context it needs, how it validates, how it turns data
 * into API requests, and whether its values are safe to persist in a
 * local draft. The registry is a total record over
 * `StructuredQuestionType` — adding a member to the union refuses to
 * compile until a definition exists.
 */
export interface StructuredTypeDefinition<
  K extends StructuredQuestionType = StructuredQuestionType,
> {
  type: K;
  component: ComponentType<StructuredInputProps>;
  requires: readonly StructuredContextKey[];
  /** Questionnaire subject types this structured type may appear on —
   *  gates the studio's picker and the fill renderer. */
  subjects: readonly SubjectType[];
  /**
   * `"serialize"` — values are plain user input, safe to store in a local
   * draft and restore later.
   * Server-backed values retain their initial context so draft recovery
   * can reconcile clinician edits with fresh clinical records.
   * `"exclude"` — values cannot round-trip through JSON (for example,
   * `files` carries raw `File` objects).
   */
  draftPolicy: "serialize" | "exclude";
  /** Submit-time validation over the recorded entries (already narrowed
   *  to this type's data shape). Optional — types without client rules
   *  rely on server-side validation. */
  validate?: (
    data: DataTypeFor<K>[],
    questionId: string,
    required: boolean,
  ) => QuestionValidationError[];
  /** Turn recorded entries into raw batch requests. May return [] when
   *  the context it needs is missing or nothing changed (dirty-row
   *  filtering). Async because some types transform payloads (files →
   *  base64). */
  buildRequests: (
    data: DataTypeFor<K>[],
    context: StructuredRequestContext,
  ) => Promise<StructuredBatchEntry[]>;
}
import { DiagnosisQuestion } from "@/components/Questionnaire/QuestionTypes/DiagnosisQuestion";

import type {
  StructuredInputProps,
  StructuredTypeDefinition,
} from "@/components/QuestionnaireV2/structured/types";
import { structuredReferenceId } from "@/components/QuestionnaireV2/structured/types";
import { sanitizeNote, useLegacyResponseCallback } from "./adapt";

function DiagnosisInput(props: StructuredInputProps) {
  const updateResponse = useLegacyResponseCallback(props.onChange);
  if (!props.patientId || !props.encounterId) return null;
  return (
    <DiagnosisQuestion
      patientId={props.patientId}
      encounterId={props.encounterId}
      question={props.question}
      questionnaireResponse={props.response}
      updateQuestionnaireResponseCB={updateResponse}
      initializeQuestionnaireResponseCB={props.onInitializeResponse}
      disabled={props.disabled}
    />
  );
}

export const diagnosisDefinition: StructuredTypeDefinition<"diagnosis"> = {
  type: "diagnosis",
  component: DiagnosisInput,
  requires: ["patientId", "encounterId"],
  subjects: ["encounter"],
  draftPolicy: "serialize",
  buildRequests: async (diagnoses, { patientId, encounterId, questionId }) => {
    // Only edited rows submit — prefetched server rows ride along in the
    // response values and must not re-upsert untouched.
    const dirty = diagnoses.filter((diagnosis) => diagnosis.dirty);
    // `subjects` is encounter-only, so a patient is always in scope here —
    // narrowed rather than asserted (the context type is optional for
    // plugin types that declare a resource subject).
    if (!patientId || !encounterId || dirty.length === 0) return [];
    return [
      {
        url: `/api/v1/patient/${patientId}/diagnosis/upsert/`,
        method: "POST",
        body: {
          datapoints: dirty.map((diagnosis) => ({
            ...diagnosis,
            note: sanitizeNote(diagnosis.note),
            encounter: encounterId,
          })),
        },
        reference_id: structuredReferenceId("diagnosis", questionId),
      },
    ];
  },
};
