          datapoints: dirty.map((diagnosis) => ({
            ...diagnosis,
            note: sanitizeNote(diagnosis.note),
            encounter: encounterId,
          })),
        },
        reference_id: structuredReferenceId("diagnosis", questionId),
      },
    ];
  },
};
