  on_hold: "yellow",
  intended: "indigo",
  not_taken: "secondary",
  unknown: "secondary",
  entered_in_error: "destructive",
} as const satisfies Record<
  MedicationStatementStatus,
  React.ComponentProps<typeof Badge>["variant"]
>;

export type MedicationStatement = {
  readonly id: string;
